// LRU (Least Recently Used): đầy thì loại mục lâu không dùng nhất. Map giữ thứ tự chèn nên rất tiện.
class LRU {
  constructor(max) { this.max = max; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return undefined;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v);          // đưa lên "mới dùng nhất"
    return v;
  }
  set(k, v) {
    if (this.m.has(k)) this.m.delete(k);
    this.m.set(k, v);
    if (this.m.size > this.max) this.m.delete(this.m.keys().next().value);   // loại cũ nhất
  }
}

const c = new LRU(2);
c.set("a", 1); c.set("b", 2); c.get("a"); c.set("c", 3);   // b bị loại
console.log([...c.m.keys()].join(","));

