let dbCalls = 0;
const db = (id) => { dbCalls++; return { id }; };
const cache = new Map();
function getUser(id) {
  if (cache.has(id)) return cache.get(id);
  const u = db(id);
  cache.set(id, u);
  return u;
}
getUser(1); getUser(1); getUser(1); getUser(2);
