let fetches = 0;
const slow = async (k) => { fetches++; await new Promise((r) => setTimeout(r, 10)); return "val-" + k; };
function once(fn) {
  const inflight = new Map();
  return (k) => {
    if (!inflight.has(k)) inflight.set(k, fn(k));
    return inflight.get(k);
  };
}
const load = once(slow);
(async () => {
  const rs = await Promise.all([load("x"), load("x"), load("x")]);
  console.log(fetches + "|" + rs[0]);
})();
